tool_calls.args:
{"command":"{
echo "Subject: $(openssl x509 -in /app/ssl/server.crt -noout -subject)"
echo "Validity dates (OpenSSL format):"
openssl x509 -in /app/ssl/server.crt -noout -dates
echo "Validity dates (YYYY-MM-DD format):"
echo -n "notBefore="; date -d "$(openssl x509 -in /app/ssl/server.crt -noout -startdate | cut -d= -f2)" +%Y-%m-%d
echo -n "notAfter="; date -d "$(openssl x509 -in /app/ssl/server.crt -noout -enddate | cut -d= -f2)" +%Y-%m-%d
echo "SHA-256 Fingerprint:"
openssl x509 -in /app/ssl/server.crt -noout -fingerprint -sha256
} | tee /app/ssl/verification.txt && echo "---" && cat /app/ssl/verification.txt","description":"Create verification file with cert details"}
